const STREET_POOL = [
  "Market Street","Main Road","Station Road","Hospital Road","School Lane",
  "Church Road","Beach Road","Airport Road","Kariakoo Street","Mkwepu Street",
  "Uhuru Street","Independence Avenue","Nyerere Road","Kawawa Road","Morogoro Road",
  "Bagamoyo Road","Ali Hassan Mwinyi Road","Sam Nujoma Road","Mkunguni Street",
  "Gerezani Street","Kongo Street","India Street","Arab Street","New Dar Road",
  "Old Dar Road","Golf Course Road","Fire Station Road","Post Office Road",
];

let _seed = 42;
function _random(): number {
  _seed = (_seed * 1664525 + 1013904223) & 0x7FFFFFFF;
  return _seed / 0x7FFFFFFF;
}

function _pick<T>(arr: readonly T[]): T {
  return arr[Math.floor(_random() * arr.length)];
}

export function getRegions(): Region[] { return REGIONS; }

export function getDistrictsByRegion(regionSlug: string): District[] {
  return DISTRICTS.filter(d => d.regionSlug === regionSlug);
}

export function getWardsByDistrict(regionSlug: string, districtSlug: string): { name: string; slug: string }[] {
  const ws = WARDS[regionSlug]?.[districtSlug] ?? [];
  return ws.map(name => ({ name, slug: name.toLowerCase().replace(/s+/g, "-") }));
}

export function getStreets(_regionSlug: string, _districtSlug: string, _wardSlug: string): { name: string; postcode: string }[] {
  const count = Math.floor(_random() * 4);
  if (count === 0) return [];
  const streets: { name: string; postcode: string }[] = [];
  const used = new Set<string>();
  for (let i = 0; i < count; i++) {
    let name = _pick(STREET_POOL);
    while (used.has(name)) name = _pick(STREET_POOL);
    used.add(name);
    const postcode = String(10000 + Math.floor(_random() * 90000));
    streets.push({ name, postcode });
  }
  return streets;
}